"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["54586"],{72371(e,t,n){n.d(t,{Ay:()=>l,RM:()=>r});var s=n(74848),o=n(28453),i=n(66422);let r=[];function a(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"teaching-you-to-trade-stocks-90-auxiliary-judgment-for-bardo-phase-ending-time",children:"Teaching You to Trade Stocks 90: Auxiliary Judgment for Bardo Phase Ending Time"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2007/12/3 22:33:08"}),"\n"]}),"\n",(0,s.jsxs)("div",{style:{color:"#FF0000",fontSize:"18px",fontWeight:"500"},children:[(0,s.jsx)(t.p,{children:"Note: what's given here is an auxiliary judgment for the bardo phase ending time, not an absolute judgment. Just like using MACD to judge divergence, it's only auxiliary. But because the accuracy is extremely high, and the absolute judgment is too complex to be practical, this can generally be used for making judgments. Generally speaking, the effectiveness of this auxiliary judgment for bardo phase ending time can approach 100%, with very few exceptions."}),(0,s.jsx)(t.p,{children:"Of course, since it's auxiliary, technique and proficiency are crucial. It's like performing acrobatics \u2014 a well-trained performer rarely makes mistakes on stage, while someone with no training at all will definitely mess up the moment they step up."}),(0,s.jsx)(t.p,{children:"This auxiliary judgment utilizes an indicator available in all software: Bollinger Bands. Generally displayed as BOLL in software. This indicator usually has three lines \u2014 upper, middle, and lower bands. Generally speaking, running above the upper band or below the lower band indicates a super-strong state. This inevitably occurs during hub shifts \u2014 the only difference is the former represents an upward super-strong state, while the latter represents a downward super-strong state."}),(0,s.jsx)(t.p,{children:"Note, this indicator provides an excellent auxiliary judgment for second-type buy/sell points, and sometimes can also be used to judge first-type buy/sell points. Generally speaking, falling back below the upper band from above, or rising back above the lower band from below, both represent transitioning from a super-strong zone to a normal zone. At this point, if a subsequent rise or decline creates a new high or new low but fails to effectively return to the super-strong zone, it means a bardo state has been entered \u2014 that is, a first-type buy/sell point has appeared."}),(0,s.jsx)(t.p,{children:"But even more effective is the auxiliary judgment for second-type buy/sell points. Generally speaking, upon entering the bardo state, the upper and lower bands will react with a lag \u2014 meaning they only turn after the first pullback or bounce, and then the subsequent move up or down. At the point when the upper and lower bands turn, they often become the strongest resistance and support, causing second-type buy/sell points to be constructed below or above them. One example is the second-type sell point formed at the Shanghai market's 6004 level, and another example is the second-type buy/sell point on June 20th."}),(0,s.jsxs)("div",{style:{textAlign:"left"},children:[(0,s.jsx)("img",{src:(0,i.Ay)("/img/stocks/090/1A0001_d.png")}),(0,s.jsx)("br",{}),(0,s.jsx)("br",{})]}),(0,s.jsx)(t.p,{children:"For individual stocks, 000938 is a classic example \u2014 the first-type sell point on September 14th, the second-type sell point on October 8th, absolutely textbook. 000999's first-type sell point on October 10th and second-type sell point on November 6th are equally textbook. There are too many such examples, and they work equally effectively across different levels."}),(0,s.jsxs)("div",{style:{textAlign:"left"},children:[(0,s.jsx)("img",{src:(0,i.Ay)("/img/stocks/090/000938_d.png")}),(0,s.jsx)("br",{}),(0,s.jsx)("br",{})]}),(0,s.jsxs)("div",{style:{textAlign:"left"},children:[(0,s.jsx)("img",{src:(0,i.Ay)("/img/stocks/090/000999_d.png")}),(0,s.jsx)("br",{}),(0,s.jsx)("br",{})]}),(0,s.jsx)(t.p,{children:"Note, some people may say the two examples above are this ID's own stocks, so of course they'd be accurate. Actually, other stocks are even more precise. For example, 000002 \u2014 this stock is popular enough for the masses, right? Look at its weekly chart: the week of 40.78 yuan \u2014 what exactly happened to form a weekly first-type sell point?"}),(0,s.jsxs)("div",{style:{textAlign:"left"},children:[(0,s.jsx)("img",{src:(0,i.Ay)("/img/stocks/090/000002_w.png")}),(0,s.jsx)("br",{}),(0,s.jsx)("br",{})]}),(0,s.jsx)(t.p,{children:"However, the most useful application of Bollinger Bands is the pre-judgment of bardo ending time. Generally speaking, the contraction of Bollinger Bands is the best indication of when the bardo will end. But there's some technique involved \u2014 a 1-minute level doesn't necessarily mean looking at 1-minute Bollinger Bands. For example, in the chart below, a 5-minute bardo process corresponds to looking at the 30-minute Bollinger Bands."}),(0,s.jsx)(t.p,{children:"Generally speaking, when the Bollinger Bands at a certain level contract, it means some bardo process at a lower level is about to either expand in level or end. This typically corresponds to a third-type buy/sell point at the appropriate level."}),(0,s.jsx)(t.p,{children:"Please study the chart below carefully \u2014 it also contains the descending channel mentioned this afternoon. You can see how close the price is to the upper band now."}),(0,s.jsx)(t.p,{children:"Note, this auxiliary judgment requires slightly more technique than the MACD technique. You must constantly study charts and summarize your own experience to gain proficiency. This ID here is only pointing at the moon for everyone. To make the moon your own, you still need to put in the effort yourself."}),(0,s.jsxs)("div",{style:{textAlign:"left"},children:[(0,s.jsx)("img",{src:(0,i.Ay)("/img/stocks/090/1.jpg")}),(0,s.jsx)("br",{}),(0,s.jsx)("br",{})]})]})]})}function l(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(a,{...e})}):a(e)}},77771(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>a,contentTitle:()=>l,toc:()=>h,assets:()=>c});var s=JSON.parse('{"id":"stocks/090","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/090.md","sourceDirName":"stocks","slug":"/stocks/090","permalink":"/en/stocks/090","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"090","title":"","hide_table_of_contents":true,"sidebar_label":"Teaching You Stock Trading 90: Auxiliary Judgment for Timing the End of the Mid-Yin Phase (2007/12/3 22:33:08)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"Short-term facing a turning point (2007/12/3 15:26:04)","permalink":"/en/stocks/marketchange"},"next":{"title":"Breakout Pullback, Tomorrow and the Day After Are Key (2007/12/4 15:29:26)","permalink":"/en/stocks/fallafterbreak"}}'),o=n(74848),i=n(28453),r=n(72371);let a={id:"090",title:"",hide_table_of_contents:!0,sidebar_label:"Teaching You Stock Trading 90: Auxiliary Judgment for Timing the End of the Mid-Yin Phase (2007/12/3 22:33:08)"},l,c={},h=[...r.RM];function d(e){return(0,o.jsx)(r.Ay,{})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>a});var s=n(96540);let o={},i=s.createContext(o);function r(e){let t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);